I’d try adding analytic gradients to the SLSQP local optimizer. It should help convergence and final constraint satisfaction without changing the overall packing strategy.

```python
import math
import time
import random


def _grid(n):
    side = math.ceil(math.sqrt(n))
    radius = 0.5 / side - 1e-12
    return [
        [(c + 0.5) / side, (row + 0.5) / side, radius]
        for row in range(side)
        for c in range(side)
    ][:n]


def _base26():
    r = 1.0 / (2.0 + 5.0 * math.sqrt(3.0)) - 1e-9
    h = math.sqrt(3.0) * r
    circles = []

    y = r
    for j in range(5):
        circles.append([r + 2.0 * r * j, y, r])
    y += h
    for j in range(4):
        circles.append([2.0 * r + 2.0 * r * j, y, r])
    y += h
    for j in range(5):
        circles.append([r + 2.0 * r * j, y, r])
    y += h
    for j in range(5):
        circles.append([r + 2.0 * r * j, y, r])
    y += h
    for j in range(4):
        circles.append([2.0 * r + 2.0 * r * j, y, r])
    y += h
    for j in range(3):
        circles.append([2.0 * r + 2.0 * r * j, y, r])

    return circles


def _valid(circles, tol=1e-9):
    n = len(circles)
    for x, y, r in circles:
        if r <= 0:
            return False
        if x - r < -tol or x + r > 1.0 + tol or y - r < -tol or y + r > 1.0 + tol:
            return False
    for i in range(n):
        xi, yi, ri = circles[i]
        for j in range(i + 1, n):
            xj, yj, rj = circles[j]
            dist = math.hypot(xi - xj, yi - yj)
            if dist < (ri + rj) - 1e-9:
                return False
    return True


def _local_improve(circles, time_limit=2.0, seed=0):
    start = time.time()
    n = len(circles)
    if n == 0:
        return circles

    import numpy as np
    from scipy.optimize import minimize

    v0 = np.array([v for c in circles for v in c], dtype=float)

    def unpack(v):
        x = v[0:n].copy()
        y = v[n:2*n].copy()
        r = v[2*n:3*n].copy()
        return x, y, r

    def obj(v):
        return -float(np.sum(unpack(v)[2]))

    def obj_jac(v):
        g = np.zeros(3 * n)
        g[2 * n:] = -1.0
        return g

    bounds = []
    for _ in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 0.5))

    cons = []

    for i in range(n):
        def c1(v, i=i):
            x, y, r = unpack(v)
            return float(x[i] - r[i])

        def c1_jac(v, i=i):
            g = np.zeros(3 * n)
            g[i] += 1.0
            g[2 * n + i] -= 1.0
            return g

        cons.append({'type': 'ineq', 'fun': c1, 'jac': c1_jac})

        def c2(v, i=i):
            x, y, r = unpack(v)
            return float(1.0 - x[i] - r[i])

        def c2_jac(v, i=i):
            g = np.zeros(3 * n)
            g[i] -= 1.0
            g[2 * n + i] -= 1.0
            return g

        cons.append({'type': 'ineq', 'fun': c2, 'jac': c2_jac})

        def c3(v, i=i):
            x, y, r = unpack(v)
            return float(y[i] - r[i])

        def c3_jac(v, i=i):
            g = np.zeros(3 * n)
            g[n + i] += 1.0
            g[2 * n + i] -= 1.0
            return g

        cons.append({'type': 'ineq', 'fun': c3, 'jac': c3_jac})

        def c4(v, i=i):
            x, y, r = unpack(v)
            return float(1.0 - y[i] - r[i])

        def c4_jac(v, i=i):
            g = np.zeros(3 * n)
            g[n + i] -= 1.0
            g[2 * n + i] -= 1.0
            return g

        cons.append({'type': 'ineq', 'fun': c4, 'jac': c4_jac})

    for i in range(n):
        for j in range(i + 1, n):
            def cp(v, i=i, j=j):
                x, y, r = unpack(v)
                return float((x[i] - x[j]) ** 2 + (y[i] - y[j]) ** 2 - (r[i] + r[j]) ** 2)

            def cp_jac(v, i=i, j=j):
                g = np.zeros(3 * n)
                x, y, r = unpack(v)
                dx = x[i] - x[j]
                dy = y[i] - y[j]
                dr = r[i] + r[j]

                g[i] = 2.0 * dx
                g[n + i] = 2.0 * dy
                g[2 * n + i] = -2.0 * dr

                g[j] = -2.0 * dx
                g[n + j] = -2.0 * dy
                g[2 * n + j] = -2.0 * dr

                return g

            cons.append({'type': 'ineq', 'fun': cp, 'jac': cp_jac})

    if time.time() - start > time_limit:
        return circles

    res = minimize(
        obj,
        v0,
        method='SLSQP',
        bounds=bounds,
        constraints=cons,
        jac=obj_jac,
        options={'maxiter': 20, 'ftol': 1e-12, 'disp': False},
    )

    if time.time() - start > time_limit:
        return circles
    if res.x is None:
        return circles

    v = res.x
    x, y, r = unpack(v)
    cand = [[float(x[i]), float(y[i]), float(r[i])] for i in range(n)]

    if _valid(cand, tol=1e-9) and sum(c[2] for c in cand) > sum(c[2] for c in circles) + 1e-12:
        return cand
    return circles


def solve(n, seed, budget):
    if n == 26:
        base = _base26()
        best = base
        best_sum = sum(c[2] for c in base)

        rng = random.Random(seed)
        pert = [list(c) for c in base]
        for c in pert:
            c[0] = min(1.0, max(0.0, c[0] + rng.uniform(-0.004, 0.004)))
            c[1] = min(1.0, max(0.0, c[1] + rng.uniform(-0.004, 0.004)))
            c[2] = max(1e-6, c[2] * rng.uniform(0.97, 1.03))

        starts = [base, pert]
        for idx, cand in enumerate(starts):
            remaining = (budget if budget is not None else 15.0) - (idx * 2.0)
            if remaining <= 0:
                break
            improved = _local_improve(cand, time_limit=min(2.0, remaining), seed=seed)
            if _valid(improved, tol=1e-9):
                s = sum(c[2] for c in improved)
                if s > best_sum + 1e-12:
                    best = improved
                    best_sum = s

        return best
    return _grid(n)
```
